# Store a memory
alchemyst.v1.context.add({
"content": "User said: I'm vegan and allergic to peanuts",
"context_type": "conversation",
"metadata": {
"group_name": ["preferences", "alice"]
}
})
print("✅ Memory stored!")
# Later: Retrieve memories
result = alchemyst.v1.context.search(
limit=10,
body_metadata={"group_name": ["preferences", "alice"]}
)
